import { SITE_URL } from './site';

/**
 * llms.txt files are generated by the API (api.pphat.me, `apps/modules/llms`)
 * and served here under the site's own paths:
 *
 *   site                        API
 *   /llms.txt                   /llms.txt
 *   /posts/<slug>/llms.txt      /articles/<slug>/llms.txt
 *   /projects/<slug>/llms.txt   /projects/<slug>/llms.txt
 *   /about/llms.txt             /about/llms.txt
 *   /contact/llms.txt           /contact/llms.txt
 *
 * The API writes cross-links using the origin that requested them (the API
 * itself, when fetched server-side) and calls posts "articles", so links are
 * rewritten to the site's URLs before serving.
 */
const API_ORIGIN = new URL(process.env.NEXT_PUBLIC_APP_API || 'https://api.pphat.me').origin;

function toSiteLinks(text: string): string {
    return text
        .replaceAll(`${API_ORIGIN}/articles/`, `${SITE_URL}/posts/`)
        .replaceAll(`${API_ORIGIN}/`, `${SITE_URL}/`)
        .replaceAll(`${SITE_URL}/articles/`, `${SITE_URL}/posts/`);
}

function textResponse(body: string, status: number): Response {
    return new Response(body, {
        status,
        headers: {
            // Markdown, served as text/plain so browsers display it (same as the API).
            'Content-Type': 'text/plain; charset=utf-8',
            // Keep these machine-readable twins out of search results.
            'X-Robots-Tag': 'noindex',
            'Cache-Control': status === 200 ? 'public, max-age=300, s-maxage=3600' : 'no-store',
        },
    });
}

/**
 * Fetch an llms.txt document from the API and serve it with site links.
 * `apiPath` must be one of the fixed paths above, built with an encoded slug.
 */
export async function proxyLlms(apiPath: string, tags: string[]): Promise<Response> {
    try {
        const res = await fetch(`${API_ORIGIN}${apiPath}`, {
            headers: { Accept: 'text/plain' },
            next: { tags: ['llms', ...tags], revalidate: 3600 },
        });
        const body = await res.text();
        if (res.ok) return textResponse(toSiteLinks(body), 200);
        if (res.status === 404) return textResponse(toSiteLinks(body), 404);
        console.error(`llms.txt: API ${apiPath} returned ${res.status}`);
    } catch (error) {
        console.error(`llms.txt: API ${apiPath} failed:`, error);
    }
    return textResponse('# Temporarily unavailable\n\n> Please try again later.\n', 503);
}
